#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;long long x;scanf("%d %lld",&n,&x);
vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
int lo=0,hi=n-1;bool found=false;
while(lo<=hi){int mid=lo+(hi-lo)/2;
if(a[mid]==x){found=true;break;}
if(a[mid]<x)lo=mid+1;else hi=mid-1;}
printf("%s\n",found?"YES":"NO");return 0;}

